                nr, nc = r + dr, c + dc
                if nr < 0 or nr >= H or nc < 0 or nc >= W:
                    can_move = False
                    break
                new_cells.append((nr, nc))

            if can_move:
                # Check collision with other pieces
                collision = False
                for j, other in enumerate(current_pieces):
                    if i == j:
                        continue
